import{_ as s,o as a,c as o,a4 as i,ae as n,af as c,ag as l,ah as t,ai as p,aj as d,ak as r,al as _,am as m,an as g,ao as h,ap as x,aq as b,ar as u,as as f,at as k,au as S,av as P,aw as M}from"./chunks/framework.DAe4SYBh.js";const W=JSON.parse('{"title":"Sensor Sample 适配笔记","description":"","frontmatter":{},"headers":[],"relativePath":"goke/v500/sensor sample 适配笔记.md","filePath":"goke/v500/sensor sample 适配笔记.md"}'),v={name:"goke/v500/sensor sample 适配笔记.md"};function I(A,e,R,C,D,y){return a(),o("div",null,[...e[0]||(e[0]=[i(`<h1 id="sensor-sample-适配笔记" tabindex="-1">Sensor Sample 适配笔记 <a class="header-anchor" href="#sensor-sample-适配笔记" aria-label="Permalink to “Sensor Sample 适配笔记”">​</a></h1><p>适配新 sensor 的大体原则：选择一款同一厂商、规格相近的 sensor 驱动来做修改，先保证软件编译通路 OK，再保证硬件通路 OK，最后再调试效果。</p><p>以 gk7605v100 上适配 imx290（2M 30fps）为例，以 imx307（2M 30fps）驱动为参考，因为两者的分辨率、帧率、设备地址、地址位宽、数据位宽都一样。</p><h2 id="_1-确认主芯片规格" tabindex="-1">1. 确认主芯片规格 <a class="header-anchor" href="#_1-确认主芯片规格" aria-label="Permalink to “1. 确认主芯片规格”">​</a></h2><p>确认主芯片规格的目的，是看将要适配的 sensor 的初始化时序能否跑起来。例如 gk7205v200 不支持行 WDR，分辨率最大只能 3M，具体情况视主芯片规格而定。适配 sensor 主要关注以下几点：</p><ul><li>支持输入频率上限（一般都会支持，不是重点）。</li><li>主芯片目前都是 master 模式（slave 模式主要用于拼接，暂时没有）。</li><li>支持最大分辨率和帧率的组合，如线性 5M 30fps（imx335）。</li><li>支持线性、帧 WDR、行 WDR（gk7205v200、gk7202v300 不支持）。</li><li>MIPI CSI-2 lane 数：gk7605v100 为 4 lane，gk7205v200 为 2 lane；LVDS 暂时不涉及。</li></ul><h2 id="_2-sensor-驱动" tabindex="-1">2. Sensor 驱动 <a class="header-anchor" href="#_2-sensor-驱动" aria-label="Permalink to “2. Sensor 驱动”">​</a></h2><p>写驱动之前要准备好 sensor 初始化序列，一般由厂商提供，需和厂商确认以下几点：</p><ul><li>sensor 工作在主模式下，从模式暂时不涉及。</li><li>sensor 的时钟频率为 37.125MHz。</li><li>sensor 通过 I2C 读写。</li><li>sensor 通过 MIPI CSI-2 传输数据，lane 数为 4。</li><li>线性、分辨率 2M、帧率 30fps、RAW12，ADBIT 为 12bit。</li></ul><p>在 <code>sensor/gk7205v200</code> 目录下新建一个文件夹，为了保持风格一致取名为 <code>sony_imx290</code>，并在当前目录下的 Makefile 中添加 <code>objects += sony_imx290</code>。</p><p>进入 <code>sony_imx290</code> 文件夹，新建以下四个文件，内容从 <code>sony_imx307</code> 拷贝过来：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>├── imx290_cmos.c         // ae、awb、blc、isp_default、sns_reg，功能调试时再做修改</span></span>
<span class="line"><span>├── imx290_cmos_ex.h      // 算法参数，编译 sample 时会做稍微修改</span></span>
<span class="line"><span>├── imx290_sensor_ctl.c   // 初始化序列</span></span>
<span class="line"><span>└── Makefile              // 编译脚本</span></span></code></pre></div><h2 id="_3-编译-sensor-库" tabindex="-1">3. 编译 Sensor 库 <a class="header-anchor" href="#_3-编译-sensor-库" aria-label="Permalink to “3. 编译 Sensor 库”">​</a></h2><p>编译 sensor 的目的是保证 sensor 驱动总体框架是 OK 的，后面会根据 sample 下的编译适当做些修改，具体情况看编译报错信息。</p><p>在 <code>sony_imx290</code> 目录下单独编译 sensor 库，编译之前先对驱动做以下几处修改：</p><ul><li>Makefile 中将 <code>libsns_imx307</code> 改为 <code>libsns_imx290</code>。</li><li><code>ctl.c</code> 中，把 imx307 线性 1080p30fps 的初始化序列替换成 imx290 的初始化序列。</li><li>其余修改可用全局替换，把 307 替换成 290。</li></ul><blockquote><p>注：SHS1、GAIN、VMAX、HCG、HMAX 这几个寄存器地址相同，未做修改；SHS2、RHS1、RHS2、Y_OUT_SIZE 这几个寄存器是 WDR 时需要配置的，后面适配 WDR 模式再做介绍，寄存器地址参考 datasheet。</p></blockquote><p><code>cmos.c</code> 里面的相关功能函数暂时不做修改，后面调试基本功能和图像质量的时候再讲解。</p><h2 id="_4-sample-下-sensor-的基本通路" tabindex="-1">4. Sample 下 Sensor 的基本通路 <a class="header-anchor" href="#_4-sample-下-sensor-的基本通路" aria-label="Permalink to “4. Sample 下 Sensor 的基本通路”">​</a></h2><p>sensor 基本通路的适配是指从 sensor 到 ISP 的通路能够起来，暂且先不管图像效果，主要涉及 mipi、dev、pipe、chn、isp_pub 属性的适配等，相关属性可参考 imx307。</p><p><img src="`+n+'" alt="sample 中 sensor 通路相关属性"></p><p>经过以上 3 步，在 <code>out/lib</code> 目录下会有 imx290 的动态库和静态库生成，现在主要是在已有的 sample 框架下适配 imx290 的 mipi → vi → isp 软件通路：</p><ul><li><p><strong>设置 mipi 属性</strong>：在函数 <code>SAMPLE_COMM_VI_GetComboAttrBySns</code> 中实现 imx290 的 <code>combo_dev_attr_t</code>，可参考 imx307 的 mipi 属性。devno、lane_id 不匹配的话，后期 mipi 没有数据出来。</p><p><img src="'+c+'" alt="mipi 属性配置 1"></p><p><img src="'+l+'" alt="mipi 属性配置 2"></p></li><li><p><strong>设置 dev 属性</strong>：在函数 <code>SAMPLE_COMM_VI_GetDevAttrBySns</code> 中实现 imx290 的 <code>VI_DEV_ATTR_S</code>。</p><p><img src="'+t+'" alt="dev 属性配置 1"></p><p><img src="'+p+'" alt="dev 属性配置 2"></p></li><li><p><strong>设置 pipe 属性</strong>：在函数 <code>SAMPLE_COMM_VI_GetPipeAttrBySns</code> 中实现 imx290 的 <code>VI_PIPE_ATTR_S</code>。</p><p><img src="'+d+'" alt="pipe 属性配置"></p></li><li><p><strong>设置 chn 属性</strong>：在函数 <code>SAMPLE_COMM_VI_GetChnAttrBySns</code> 中实现 imx290 的 <code>VI_CHN_ATTR_S</code>。</p><p><img src="'+r+'" alt="chn 属性配置"></p></li><li><p><strong>设置 isp_pub 属性</strong>：在函数 <code>SAMPLE_COMM_ISP_GetIspAttrBySns</code> 中实现 imx290 的 <code>ISP_PUB_ATTR_S</code>。</p><p><img src="'+_+'" alt="isp_pub 属性配置 1"></p><p><img src="'+m+'" alt="isp_pub 属性配置 2"></p></li><li><p><strong>注册 sensor 对象</strong>：在函数 <code>SAMPLE_COMM_ISP_GetSnsObj</code> 中增加 imx290，并在 <code>sns_ctrt.h</code> 中添加 <code>extern ISP_SNS_OBJ_S stSnsImx290Obj;</code>。</p><p><img src="'+g+'" alt="SAMPLE_COMM_ISP_GetSnsObj 修改"></p></li><li><p><strong>验证通路</strong>：执行 <code>./sample_vio 0</code>（<code>./sample_vio -h</code> 查看用例）。如有信息打印出来，且在 <code>sample/vio</code> 目录下有码流生成，说明基本通路整体 OK，可进一步通过查看 proc 信息验证；如果没有码流生成，也可通过 proc 信息、I2C 读写手段排除引起错误的原因。</p><p><img src="'+h+'" alt="sample_vio 运行输出"></p></li></ul><h2 id="_5-isp-基本功能" tabindex="-1">5. ISP 基本功能 <a class="header-anchor" href="#_5-isp-基本功能" aria-label="Permalink to “5. ISP 基本功能”">​</a></h2><p>ISP 基本功能主要涉及以下函数：<code>cmos_set_image_mode</code>、<code>cmos_set_wdr_mode</code>、<code>cmos_get_isp_default</code>、<code>cmos_get_isp_black_level</code>、<code>cmos_set_pixel_detect</code>。</p><ul><li><strong><code>cmos_set_image_mode</code></strong>：根据 <code>enWDRMode</code> 和分辨率设置 <code>u8SensorImageMode</code>、<code>u32FLStd</code>、<code>u8Hcg</code>、<code>u32BRL</code> 等变量的值，其中： <ul><li><code>u8SensorImageMode</code>：表示线性、行 WDR、帧 WDR。</li><li><code>u32FLStd</code>：基准帧率下一帧的总行数，即 VMAX 寄存器中的值。根据 datasheet 可查，线性或帧 WDR 时为 <code>0x465</code>，行 WDR 10bit 时为 <code>0x4c4 * 2</code>。</li><li><code>u8Hcg</code>：帧率选择和增益选择。低两位表示帧率（1h:60fps、2h:30fps），第 4 位表示增益选择（0:LCG、1:HCG），一般默认为 0，但当 again 超出一定范围时设为 1。</li><li><code>u32BRL</code>：读出时间，一般行 WDR 时赋值为 1109，datasheet 可查。</li></ul></li><li><strong><code>cmos_set_wdr_mode</code></strong>：主要用于区分不同的 WDR 模式（线性、行 WDR、帧 WDR 等），AE 会根据不同模式进行对应的参数修改。</li><li><strong><code>cmos_get_isp_default</code></strong>：配置 ISP 算法的基本校正参数，后期图像质量调优时可以去修改。</li><li><strong><code>cmos_get_isp_black_level</code></strong>：配置 RAW 数据四个通道的黑电平，datasheet 上可查。有些 sensor 的黑电平会随 gain 值变化而漂移，需要在不同范围的 gain 值下给出不同的黑电平值。</li><li><strong><code>cmos_set_pixel_detect</code></strong>：像素校正模式时使用，不支持行 WDR。</li></ul><h2 id="_6-ae-配置" tabindex="-1">6. AE 配置 <a class="header-anchor" href="#_6-ae-配置" aria-label="Permalink to “6. AE 配置”">​</a></h2><p>AE 主要功能是动态调节 sensor 的曝光时间和增益来获取最佳图像质量，也是整个 <code>cmos.c</code> 的核心，主要涉及以下函数：<code>cmos_get_sns_regs_info</code>、<code>cmos_get_ae_default</code>、<code>cmos_again_calc_table</code>、<code>cmos_dgain_calc_table</code>、<code>cmos_get_inttime_max</code>、<code>cmos_gains_update</code>、<code>cmos_inttime_update</code>、<code>cmos_fps_set</code>、<code>cmos_slow_framerate_set</code>。</p><ul><li><strong><code>cmos_get_sns_regs_info</code></strong>：把 sensor 曝光时间、增益相关的寄存器地址赋值给 AE 模块，同时为避免生效不同步，引入 <code>u8DelayFrmNum</code> 参数，保证增益、曝光时间、isp_dgain 同时生效。</li><li><strong><code>cmos_get_ae_default</code></strong>：初步获取 AE 的默认参数，主要涉及曝光时间精度类型、again 精度类型、dgain 精度类型、ISP 数字增益、最大最小 again/dgain、曝光策略、初始化曝光时间等。如果是 WDR 模式，还需要配置曝光比，各个参数具体含义可参考《isp开发参考》。</li><li><strong><code>cmos_Xgain_calc_table</code></strong>：计算出当前 sensor 的增益值。查看 datasheet 可知计算增益的方式是线性关系还是查表关系，需与 <code>cmos_get_ae_default</code> 中的 gain 精度类型对应。datasheet 一般都会提供计算增益的方式，目前 sony 采用的都是查表方式，以 0.3dB 方式递增，表中的第一个值 1024 表示最小增益。</li><li><strong><code>cmos_gain_update</code></strong>：根据输入的 again、dgain 配置 sensor 的 gain 寄存器，当 again 大于一定数值时，会打开 HCG_MODE。</li><li><strong><code>cmos_get_inttime_max</code></strong>：只在 xto1 WDR 行模式下有效，用于计算不同曝光比下曝光时间的最大值，曝光时间限制为长曝光时间加短曝光时间的和要小于一帧长度。</li><li><strong><code>cmos_inttime_update</code></strong>：用于更新 sensor 的曝光时间。xto1 WDR 模式时会被调用 X 次，第一次传入短帧的曝光时间。</li><li><strong><code>cmos_fps_set</code></strong>：手动设置 sensor 的帧率，根据设置的帧率重新计算 VMAX、曝光时间等。需要注意的是帧率最大值一般为 30fps，最小值理论上可以非常小，但实际应用中最小 5fps（需要后期调试得到经验值）。</li><li><strong><code>cmos_slow_framerate_set</code></strong>：AE 自动降帧配置函数，根据当前曝光实际需要的行数配置 sensor 的 VMAX 寄存器，并返回实际生效行数 <code>u32FullLines</code>。</li></ul><h2 id="_7-pq-下-sensor-的基本配置" tabindex="-1">7. PQ 下 Sensor 的基本配置 <a class="header-anchor" href="#_7-pq-下-sensor-的基本配置" aria-label="Permalink to “7. PQ 下 Sensor 的基本配置”">​</a></h2><p>主要是为了实时看码流和在线调试。</p><p><img src="'+x+'" alt="PQ 工具界面"></p><h3 id="config-目录下-ini-的适配" tabindex="-1">config 目录下 .ini 的适配 <a class="header-anchor" href="#config-目录下-ini-的适配" aria-label="Permalink to “config 目录下 .ini 的适配”">​</a></h3><p>基于规格相近的 sensor 修改。</p><p><img src="'+b+'" alt="config 目录"></p><p><img src="'+u+'" alt="config .ini 适配"></p><h3 id="libs-目录" tabindex="-1">libs 目录 <a class="header-anchor" href="#libs-目录" aria-label="Permalink to “libs 目录”">​</a></h3><p>放置 <code>.so</code> 文件。</p><p><img src="'+f+`" alt="libs 目录"></p><h3 id="网络与调试环境准备" tabindex="-1">网络与调试环境准备 <a class="header-anchor" href="#网络与调试环境准备" aria-label="Permalink to “网络与调试环境准备”">​</a></h3><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ifconfig eth0 down</span></span>
<span class="line"><span>ifconfig eth0 hw ether xx:xx:xx:xx:xx:xx</span></span>
<span class="line"><span>ifconfig eth0 xxx.xxx.xxx.xxx netmask 255.255.255.0</span></span>
<span class="line"><span>route add default gw xxx.xxx.xxx.xxx</span></span>
<span class="line"><span>telnetd &amp;</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>mount -t nfs -o nolock -o tcp 192.168.146.200:/home/xxx /mnt</span></span>
<span class="line"><span>cd /mnt/gk_linux/sdk/out/gk7205v300/ko</span></span>
<span class="line"><span>./loadgk7605v100 -i -sensor sp2308 -osmem 32M -board demo -yuv0 0</span></span>
<span class="line"><span>cd /mnt/gk_linux/sdk/tools/pq-tool/pq-board-v1.0.0.0/</span></span>
<span class="line"><span>./IspTool.sh -a sp2308 0</span></span></code></pre></div><h3 id="查看码流" tabindex="-1">查看码流 <a class="header-anchor" href="#查看码流" aria-label="Permalink to “查看码流”">​</a></h3><p>正常情况业务已经跑起来，可以打开码流工具，连上 IP 实时看码流。</p><p><img src="`+k+'" alt="码流工具"></p><p><img src="'+S+'" alt="码流画面"></p><h3 id="在线调试" tabindex="-1">在线调试 <a class="header-anchor" href="#在线调试" aria-label="Permalink to “在线调试”">​</a></h3><p>需要调试的话，打开调试工具。</p><p><img src="'+P+'" alt="调试工具"></p><p>“1”处出报错不用管，点“2”、点“3”、点 connect 即可，后面会有 <code>Connected to [192.168.147.210(4321)] successfully</code>。</p><p><img src="'+M+'" alt="调试工具连接成功"></p>',51)])])}const O=s(v,[["render",I]]);export{W as __pageData,O as default};
